import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"健力士 Guinness plc","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/健力士.md","filePath":"03_companies/健力士.md"}'),o={name:"03_companies/健力士.md"};function i(s,a,n,h,c,u){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="健力士-guinness-plc" tabindex="-1">健力士 Guinness plc <a class="header-anchor" href="#健力士-guinness-plc" aria-label="Permalink to &quot;健力士 Guinness plc&quot;">​</a></h1><h2 id="公司简介" tabindex="-1">公司简介 <a class="header-anchor" href="#公司简介" aria-label="Permalink to &quot;公司简介&quot;">​</a></h2><p>健力士（Guinness plc）是英国历史悠久的啤酒酿造集团，以烈性黑啤酒闻名于世，业务遍及全球。1980年代中期，公司陷入一桩涉及非法酒精定价和利润操纵的丑闻（&quot;健力士事件&quot;），导致高管层动荡和声誉危机。巴菲特曾在此时期认真评估收购健力士的可行性。</p><h2 id="投资时间线" tabindex="-1">投资时间线 <a class="header-anchor" href="#投资时间线" aria-label="Permalink to &quot;投资时间线&quot;">​</a></h2><ul><li><strong>1980年代中期</strong>：健力士丑闻期间，巴菲特认真研究收购可能性</li><li><strong>评估后放弃</strong>：经过深入分析，巴菲特最终决定不进行收购</li><li><strong>后续发展</strong>：健力士通过重组走出丑闻，逐步转型为全球性饮料集团</li></ul><h2 id="巴菲特评价" tabindex="-1">巴菲特评价 <a class="header-anchor" href="#巴菲特评价" aria-label="Permalink to &quot;巴菲特评价&quot;">​</a></h2><p>巴菲特在1989年致股东信中披露了他对健力士的思考过程。当时健力士因丑闻而股价低迷，巴菲特和芒格认为这家公司的品牌价值——尤其是健力士这个全球知名的爱尔兰黑啤品牌——被市场低估了。</p><p>然而，经过进一步分析，巴菲特意识到几个关键障碍：海外收购的复杂性、对英国法律和监管环境的不熟悉、以及丑闻可能带来的潜在法律风险。最终，他选择遵守&quot;能力圈&quot;原则——不投资自己无法充分评估风险边界的公司。巴菲特强调，宁可错过一个看似诱人的机会，也不应在不了解的领域冒无法量化的风险。</p><h2 id="关键语录" tabindex="-1">关键语录 <a class="header-anchor" href="#关键语录" aria-label="Permalink to &quot;关键语录&quot;">​</a></h2><blockquote><p>&quot;我们曾经认真考虑过收购健力士。这是一家拥有强大品牌的企业，但我们对英国法律体系不够了解，对丑闻可能延伸的法律后果也无法准确评估。最终我们决定——宁可错过，也不冒险踏入能力圈之外的领域。&quot;</p></blockquote><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/1991年/翻译.html">/01_letters/1991年/翻译</a></li><li><a href="/01_letters/1992年/翻译.html">/01_letters/1992年/翻译</a></li><li><a href="/01_letters/1993年/翻译.html">/01_letters/1993年/翻译</a></li></ul>',13)])])}const d=e(o,[["render",i]]);export{p as __pageData,d as default};
